function largestMeetingValue(num: number, t: number): number {
  for (let x = num + 3 * t; ; x--) {
    let a = x, b = num;
    for (let move = 0; move < t && a !== b; move++) {
      if (a > b) { a--; b++; } else { a++; b--; }
    }
    if (a === b) return x;
  }
}

