class Solution:
    def largestMeetingValue(self, num: int, t: int) -> int:
        x = num + 3 * t
        while True:
            a, b = x, num
            for _ in range(t):
                if a == b:
                    break
                if a > b:
                    a, b = a - 1, b + 1
                else:
                    a, b = a + 1, b - 1
            if a == b:
                return x
            x -= 1

